// Clean the inputs, and decide the ticket's category and priority
const j = $json;

// description: one clean line, at most 500 characters
const description = String(j.description ?? '').replace(/\s+/g, ' ').trim().slice(0, 500);

// Look at the category hint and the description together
const text = `${j.category ?? ''} ${description}`.toLowerCase();

// category: the first matching rule wins, so the most serious ones come first
let category = 'other';
if (/fraud|not (me|them|mine)|was ?n.?t (me|them)|were ?n.?t (me|them)|did ?n.?o?t make|unauthori|stolen|scam|hack|don.?t recogni/.test(text)) category = 'fraud';
else if (/feedback|suggest|idea/.test(text)) category = 'feedback';
else if (/transfer|wire|sent money|beneficiary/.test(text)) category = 'transfer';
else if (/loan|mortgage|hardship|installment/.test(text)) category = 'loan';
else if (/fee|overdraft|refund|charged me/.test(text)) category = 'fees';
else if (/\bapp\b|log ?in|password|online|new phone|locked out/.test(text)) category = 'online banking';
else if (/card|limit/.test(text)) category = 'card';
else if (/account|frozen|dormant|close|kyc|document|verify|security answer/.test(text)) category = 'account';
else if (/complain|unhappy|angry|human|manager|person/.test(text)) category = 'complaint';

// priority: from the bank's ticket policy
let priority = 'normal';
if (category === 'fraud' || /cancel.{0,30}transfer|transfer.{0,30}cancel/.test(text)) priority = 'urgent';
else if (/hardship|can.?t pay|lost (my )?job|unemploy|sick|frozen|salary|payroll/.test(text)) priority = 'high';
else if (category === 'feedback') priority = 'low';

// confirmed: only an explicit yes counts
const yesWords = ['yes', 'y', 'true', 'confirmed', '1'];

return {
  json: {
    customer_id: String(j.customer_id ?? '').replace(/\D/g, ''),
    security_answer: String(j.security_answer ?? ''),
    category,
    priority,
    description,
    confirmed: yesWords.includes(String(j.confirmed ?? '').trim().toLowerCase()) ? 'yes' : '',
    caller_number: String(j.caller_number ?? '').replace(/[^\d+]/g, '').slice(0, 20),
  },
};

// Turn the result into instructions for the agent, plus the phone alert
const j = $json;
const input = $('Clean inputs').item.json;

const obj = v => (typeof v === 'string' ? (v ? JSON.parse(v) : null) : v) || null;
const recent = obj(j.recent);
const inserted = obj(j.inserted);
const verified = !!j.verified_customer;

const responseTime = {
  urgent: 'within 4 hours',
  high: 'within 24 hours',
  normal: 'within 2 business days',
  low: 'within 5 business days',
};
const ntfyPriority = { urgent: 'urgent', high: 'high', normal: 'default', low: 'low' };

const out = { result: '', notify: false };

if (inserted) {
  // A new ticket was created
  const unverifiedNote = verified
    ? ''
    : ' Because the caller is not verified, the specialist will confirm their identity before discussing any account details.';
  out.result = `DONE. Ticket number ${inserted.ticket_id} has been created with ${inserted.priority} priority. A specialist will contact the customer ${responseTime[inserted.priority]}.${unverifiedNote} Tell the caller the ticket number and when to expect contact, in one or two short sentences.`;

  // Details for the phone alert
  out.notify = true;
  out.ntfy_title = `Ticket #${inserted.ticket_id}: ${inserted.priority.toUpperCase()} (${input.category})`;
  out.ntfy_message = `${verified ? 'Customer ' + j.verified_customer : 'UNVERIFIED caller'}: ${input.description}`;
  out.ntfy_priority = ntfyPriority[inserted.priority];
  out.ntfy_tags = inserted.priority === 'urgent' ? 'rotating_light' : 'ticket';

} else if (recent) {
  // The same customer already has a recent open ticket on this topic
  out.result = `ALREADY OPEN. This customer already has ticket number ${recent.ticket_id} about ${input.category}, opened in the last 24 hours with ${recent.priority} priority. A specialist will contact them ${responseTime[recent.priority]}. Do not create another one. Tell the caller this.`;

} else if (!input.description) {
  // The agent forgot to describe the problem
  out.result = 'NEED A SUMMARY. Write a short summary of the caller\'s problem and what they want (one or two sentences) in description, then use create_ticket again.';

} else {
  // Ask the caller first
  out.result = `NOT DONE YET. Ask the caller to confirm: "I'll create a ticket so a specialist can follow up about this. They'll contact you ${responseTime[input.priority]}. Is that okay?" Only if they say yes, use create_ticket again with the same description and confirmed set to yes.`;
}

return { json: out };
